from tests.test_verified_name_labels import FakeSheetsAPI, binding, clock_for, row_for


def test_independent_binary64_golden_vector_and_framed_utf8_bytes():
    # Independently generated by the scratch native verifier, without importing
    # the production encoder. Exact string/type/number framing is fixed here.
    assert digest.typed_payload_sha256(["Symbol", "Value"], [["SHIB-USD", 0.0000177327]]) == (
        "c634c20c4e6de64106474627af87a00f360861be4e381261eaf11f785da364e2")
    raw = (b'{"contract":"tfb.sheets-raw-typed-binary64/v1","headers":[["string","A"],["string","B"]],'
           b'"rows":[[["blank"],["bool",false]],[["number","0x1.0000000000000p+0"],["string","1"]]],"width":2}')
    assert digest.typed_payload_sha256(["A", "B"], [[None, False], [1, "1"]]) == hashlib.sha256(raw).hexdigest()


@pytest.mark.parametrize("first,second", [(None, ""), (1, 1.0), (-0.0, 0), (0.0, 0),
                                         (2**60, float(2**60)), (-1, -1.0)])
def test_only_declared_blank_and_exact_numeric_equivalences(first, second):
    assert digest.typed_payload_sha256(["Value"], [[first]]) == digest.typed_payload_sha256(["Value"], [[second]])


@pytest.mark.parametrize("first,second", [(False, 0), (True, 1), ("False", False), ("0", 0),
                                         (None, 0), (None, False), (" ", ""), ("é", "e\u0301"),
                                         ("warning", "warning "), (1.000000000000001, 1.000000000000002),
                                         (5e-324, 0), (0.0000177327, math.nextafter(0.0000177327, math.inf))])
def test_exact_types_strings_and_nonzero_double_bits_are_never_collapsed(first, second):
    assert digest.typed_payload_sha256(["Value"], [[first]]) != digest.typed_payload_sha256(["Value"], [[second]])


@pytest.mark.parametrize("headers,first,second", [
    (["A", "B"], [["a|b", "c"]], [["a", "b|c"]]),
    (["A"], [["ab"], ["c"]], [["a"], ["bc"]]),
    (["A"], [[True]], [["True"]]),
])
def test_legacy_unframed_sha8_collisions_do_not_collide_in_full_typed_digest(headers, first, second):
    assert sync._payload_sha8(headers, first) == sync._payload_sha8(headers, second)
    assert digest.typed_payload_sha256(headers, first) != digest.typed_payload_sha256(headers, second)


def test_header_cell_row_order_and_geometry_are_part_of_the_full_digest():
    headers = ["Name", "Warnings", "Rank (Overall)", "Price"]
    rows = [["Issuer", "critical:hold; raw|exact", 1, 0.0000177327], ["Other", "", 2, 7.25]]
    before = copy.deepcopy(rows)
    baseline = digest.typed_payload_sha256(headers, rows)
    for index, value in enumerate(["Different issuer", "critical:removed", 3, 0.0000177328]):
        changed = copy.deepcopy(rows)
        changed[0][index] = value
        assert digest.typed_payload_sha256(headers, changed) != baseline
    assert digest.typed_payload_sha256(headers, rows[::-1]) != baseline
    assert digest.typed_payload_sha256(headers[::-1], [row[::-1] for row in rows]) != baseline
    assert digest.typed_payload_sha256(headers, rows[:1]) != baseline
    assert digest.typed_payload_sha256(headers + ["Extra"], [row + [""] for row in rows]) != baseline
    assert digest.typed_payload_sha256(["NameChanged", *headers[1:]], rows) != baseline
    assert rows == before


@pytest.mark.parametrize("value,code", [(float("nan"), "NONFINITE_NUMBER"), (float("inf"), "NONFINITE_NUMBER"),
                                        (-float("inf"), "NONFINITE_NUMBER"), (2**53 + 1, "UNSAFE_INTEGER"),
                                        (10**400, "UNSAFE_INTEGER"), ({"private": "secret"}, "UNSUPPORTED_CELL_TYPE"),
                                        (["value"], "UNSUPPORTED_CELL_TYPE"), ("\ud800", "INVALID_UNICODE")])
def test_uncertifiable_values_have_no_fabricated_full_hash_or_private_error_content(value, code):
    rows = [[value]]
    receipt = digest.market_payload_evidence("Global_Markets", ["Value"], rows)
    assert receipt["canonical_status"] == "UNVERIFIABLE" and receipt["canonical_verified"] is False
    assert receipt["canonical_error"] == code and "written_payload_sha256" not in receipt
    assert "secret" not in str(receipt)
    assert receipt["canonical_width"] == receipt["canonical_rows"] == 1
    assert rows[0][0] is value


@pytest.mark.parametrize("headers,rows,code", [([], [], "INVALID_HEADER"), ([None], [[1]], "INVALID_HEADER"),
                                             (["A", "B"], [[1]], "INVALID_GEOMETRY"),
                                             (["A"], [[1, 2]], "INVALID_GEOMETRY"),
                                             (["A"], [None], "INVALID_GEOMETRY"),
                                             (["A"], None, "INVALID_GEOMETRY")])
def test_missing_or_ragged_structure_is_unverifiable_without_padding(headers, rows, code):
    receipt = digest.market_payload_evidence("Global_Markets", headers, rows)
    assert receipt["canonical_error"] == code and "written_payload_sha256" not in receipt


@pytest.mark.parametrize("page", ["My_Portfolio", "Top_10_Opportunities", "Performance_Log", {}, None])
def test_evidence_is_limited_to_the_four_market_pages(page):
    assert digest.market_payload_evidence(page, ["Value"], [[1]]) is None


@pytest.fixture
def writer(monkeypatch):
    for flag in ("TFB_SYNC_OHLC_FILLGUARD", "TFB_SYNC_OHLC_FILL_GUARD", "TFB_WARNINGS_COMPACT"):
        monkeypatch.setenv(flag, "off")
    monkeypatch.setenv("TFB_RANK_OVERALL_PAGE", "off")
    api = FakeSheetsAPI()
    actual = sync.SheetsWriter()
    monkeypatch.setattr(actual, "_get_service", lambda: api)
    return actual, api


@pytest.mark.parametrize("page", ["Market_Leaders", "Global_Markets", "Mutual_Funds", "Commodities_FX"])
def test_every_market_writer_records_full_intent_even_when_other_receipt_features_are_off(writer, page):
    actual, api = writer
    headers = list(get_sheet_headers(page))
    row = [""] * len(headers)
    row[headers.index("Symbol")] = "EXACT.US"
    row[headers.index("Name")] = "Exact issuer"
    assert actual.write_table("test", page, "A1", headers, [row]) == 1
    values = api.requests[-1]["body"]["values"]
    receipt = actual._write_receipts[("test", page)]
    assert receipt["written_payload_sha256"] == digest.typed_payload_sha256(values[0], values[1:])
    assert receipt["canonical_method"] == digest.CANONICAL_METHOD and receipt["canonical_version"] == 1
    assert receipt["canonical_status"] == "CANONICALIZED" and receipt["canonical_verified"] is True
    assert receipt["canonical_width"] == 115 and receipt["canonical_rows"] == 1
    assert receipt["written_payload_sha8"] == sync._payload_sha8(values[0], values[1:])
    assert receipt["evidence"] == "successful_RAW_update" and receipt["live_readback"] is False
    assert receipt["written_range"] == api.requests[-1]["range"] == f"{page}!A1"
    assert receipt["start_a1"] == "A1"


def test_receipt_binds_the_actual_nondefault_runtime_physical_start(writer):
    actual, api = writer
    headers = get_sheet_headers("Commodities_FX")
    row = [""] * len(headers)
    row[headers.index("Symbol")] = "EXACT.US"
    actual.write_table("test", "Commodities_FX", "$B$7", headers, [row])
    receipt = actual._write_receipts[("test", "Commodities_FX")]
    assert receipt["written_range"] == api.requests[-1]["range"] == "Commodities_FX!$B$7"
    assert receipt["start_a1"] == "$B$7"
    values = api.requests[-1]["body"]["values"]
    assert receipt["written_payload_sha256"] == digest.typed_payload_sha256(values[0], values[1:])


def test_receipt_captures_the_actual_post_name_rank_and_presentation_submission(writer, monkeypatch):
    actual, api = writer
    monkeypatch.setenv("TFB_RANK_OVERALL_PAGE", "enforce")
    # Stable test: read the registry inside its actual reviewed window, exactly as
    # tests/test_verified_name_labels.py does. Without this pin the test read the
    # wall clock and started failing once the committed bindings' seven-day
    # review window ended (2026-10-19 11:11 / 12:29 UTC), on main and every PR.
    # 2026-10-21: the clock is this binding's own window (clock_for), because a
    # weekly renewal can hold PE&OLES.MX while renewing others (run 39584281713).
    item = binding("PE&OLES.MX")
    real_apply = labels.apply_verified_name_labels
    now = clock_for(item)
    monkeypatch.setattr(labels, "apply_verified_name_labels", lambda p, h, r: real_apply(p, h, r, now=now))
    headers = get_sheet_headers("Global_Markets")
    row = row_for(item)
    row[headers.index("Warnings")] = "critical:raw_witness; " + row[headers.index("Warnings")]
    row[headers.index("Expected ROI 12M")] = None
    original = copy.deepcopy(row)
    before_digest = digest.typed_payload_sha256(headers, [row])
    actual.write_table("test", "Global_Markets", "A1", headers, [row])
    values = api.requests[-1]["body"]["values"]
    submitted = values[1]
    receipt = actual._write_receipts[("test", "Global_Markets")]
    assert submitted[headers.index("Name")] == item["name"]
    assert submitted[headers.index("Rank (Overall)")] == ""
    assert submitted[headers.index("Expected ROI 12M")] == ""
    assert submitted[headers.index("Warnings")].startswith(row[headers.index("Warnings")])
    assert "sheet_tuple_unknown:expected_roi_1m" in submitted[headers.index("Warnings")]
    assert receipt["written_payload_sha256"] == digest.typed_payload_sha256(headers, values[1:]) != before_digest
    assert row == original


def test_unexpected_evidence_error_is_bounded_and_not_a_cell_or_exception_dump(monkeypatch):
    def fail(_headers, _rows):
        raise RuntimeError("private secret content")

    monkeypatch.setattr(digest, "typed_payload_sha256", fail)
    receipt = digest.market_payload_evidence("Global_Markets", ["Name"], [["Issuer"]])
    assert receipt["canonical_error"] == "CANONICALIZATION_ERROR"
    assert receipt["canonical_verified"] is False and "written_payload_sha256" not in receipt
    assert "secret" not in str(receipt)


@pytest.mark.parametrize("value", [2**53 + 1, float("nan"), {"unsupported": "secret"}])
def test_successful_raw_write_survives_uncertifiable_evidence_and_keeps_actual_values(writer, value):
    actual, api = writer
    headers = get_sheet_headers("Commodities_FX")
    row = [""] * len(headers)
    row[headers.index("Symbol")] = "EXACT.US"
    row[headers.index("Industry")] = value
    assert actual.write_table("test", "Commodities_FX", "A1", headers, [row]) == 1
    submitted = api.requests[-1]["body"]["values"][1][headers.index("Industry")]
    if isinstance(value, float):
        assert math.isnan(submitted)
    else:
        assert submitted == value
    receipt = actual._write_receipts[("test", "Commodities_FX")]
    assert receipt["canonical_status"] == "UNVERIFIABLE" and receipt["canonical_verified"] is False
    assert "written_payload_sha256" not in receipt and receipt["live_readback"] is False
    assert receipt["evidence"] == "successful_RAW_update" and "secret" not in str(receipt)


def test_failed_raw_update_cannot_leave_a_previous_or_new_full_intent_receipt(writer, monkeypatch):
    actual, api = writer
    headers = get_sheet_headers("Commodities_FX")
    row = [""] * len(headers)
    actual._write_receipts[("test", "Commodities_FX")] = {"written_payload_sha256": "stale"}

    def fail():
        raise RuntimeError("permanent failure")

    monkeypatch.setattr(api, "execute", fail)
    with pytest.raises(RuntimeError, match="permanent failure"):
        actual.write_table("test", "Commodities_FX", "A1", headers, [row])
    assert ("test", "Commodities_FX") not in actual._write_receipts
